export function isRaining(weather){const code=weather?.current?.weather_code;return code==null?true:(code>=51&&code<=67)||(code>=80&&code<=82)||code>=95}
export function catWeather(weather){if(isRaining(weather)&&weather)return 'rain';if(weather?.current?.apparent_temperature<15)return 'cold';return weather?.current?.weather_code===0?'sunny':'normal'}
export function scenery(kind,weather){const room=kind==='apartment';return `<div class="art-stage" aria-hidden="true"><img class="scene-art" src="assets/${room?'apartment':'city'}-clean.png" alt="" draggable="false"><div class="rain-layer ${room?'window-rain':'city-rain'} ${isRaining(weather)?'wet':'dry'}">${Array.from({length:room?25:48},(_,i)=>`<i class="rain-streak" style="--x:${(i*37+11)%100}%;--delay:-${(i*0.31).toFixed(2)}s;--speed:${(room?1.1:0.65)+(i%5)*0.13}s;--length:${7+i%11}px"></i>`).join('')}${room?Array.from({length:5},(_,i)=>`<i class="glass-drop" style="--x:${12+i*18}%;--delay:-${i*2.3}s"></i>`).join(''):''}</div></div>`}
